import { Slider } from '@absoluteui/components/slider';

const host = document.createElement('div');
document.body.append(host);
Slider.create(host, {
  label: 'Volume',
  value: 40,
  step: 10,
  marks: true,
  valueText: (v) => `${String(v)}%`,
});

import { Slider, type SliderValueDetail } from '@absoluteui/components/slider';

const host = document.createElement('div');
const summary = document.createElement('p');
document.body.append(host, summary);
Slider.create(host, {
  label: 'Price',
  range: true,
  min: 0,
  max: 500,
  step: 10,
  value: [50, 300],
  format: { style: 'currency', currency: 'EUR', maximumFractionDigits: 0 },
  marks: [{ value: 0, label: 'Free' }, { value: 500, label: 'Max' }],
});
host.addEventListener('aui-change', (event) => {
  const { value } = (event as CustomEvent<SliderValueDetail>).detail;
  if (Array.isArray(value)) summary.textContent = `Searching ${String(value[0])} to ${String(value[1])} EUR`;
});

import { formatPlainTime, plainTime } from '@absoluteui/core';
import { Slider } from '@absoluteui/components/slider';

const host = document.createElement('div');
document.body.append(host);
// Minutes since midnight, shown as times of day.
Slider.create(host, {
  label: 'Working hours',
  range: true,
  min: 0,
  max: 23 * 60 + 30,
  step: 30,
  value: [9 * 60, 17 * 60],
  largeStep: 120,
  valueText: (m) => formatPlainTime(plainTime(Math.floor(m / 60), m % 60), { timeStyle: 'short' }),
});
